import { defineGlossary } from './engine';
import type { GlossaryTermInput } from '@/domain/content';

type T = Omit<GlossaryTermInput, 'category' | 'difficulty'> & { difficulty?: GlossaryTermInput['difficulty'] };

const group = (category: string, terms: T[]): GlossaryTermInput[] =>
  terms.map((t) => ({ difficulty: 'beginner', ...t, category }));

export const glossary = defineGlossary([
  // ───────────── Shipping & Logistics ─────────────
  ...group('shipping', [
    { id: 'carrier', term: 'Carrier', definition: 'The company that physically transports a shipment, such as a postal service, parcel company or freight line.', example: 'You buy a label from a carrier, drop the box off, and the carrier delivers it.', related: ['parcel', 'service-level', 'tracking-number'] },
    { id: 'parcel', term: 'Parcel', definition: 'A single boxed or bagged package small enough for one person to handle.', example: 'A 2 lb box of skincare products ships as a parcel.', related: ['carrier', 'freight'] },
    { id: 'service-level', term: 'Service level', definition: 'The speed tier you buy from a carrier — ground, 2-day, overnight and so on. Faster costs more.', example: 'Ground might take 4 days for $6 while overnight costs $35.', related: ['transit-time', 'carrier'] },
    { id: 'transit-time', term: 'Transit time', definition: 'How long the carrier takes to deliver after it receives the package.', example: 'A package picked up Monday and delivered Thursday had 3 days of transit time.', related: ['handling-time', 'service-level'] },
    { id: 'handling-time', term: 'Handling time', definition: 'The time between an order being placed and the package being handed to the carrier.', example: 'If you pack orders the next business day, your handling time is 1 day.', related: ['transit-time', 'fulfillment'] },
    { id: 'shipping-label', term: 'Shipping label', definition: 'The printed label with addresses, service level, barcode and tracking number. Creating one usually means postage is paid — not that the carrier has the package.', example: '“Label created” in tracking means the label exists, but no carrier scan has happened yet.', related: ['tracking-number', 'carrier'] },
    { id: 'tracking-number', term: 'Tracking number', definition: 'The unique number used to follow a shipment through each carrier scan.', example: 'Sending tracking numbers automatically reduces “where is my order?” emails.', related: ['shipping-label', 'last-mile'] },
    { id: 'first-mile', term: 'First mile', definition: 'The first leg of delivery: moving goods from the shipper into the carrier network.', example: 'Scheduling daily pickups improves your first mile.', related: ['last-mile'] },
    { id: 'last-mile', term: 'Last mile', definition: 'The final leg of delivery, from a local facility to the customer’s door — often the costliest part per package.', example: '“Out for delivery” means the package is in the last mile.', related: ['first-mile', 'tracking-number'] },
    { id: 'dimensional-weight', term: 'Dimensional weight', aliases: ['dim weight', 'volumetric weight', 'DIM'], definition: 'A weight calculated from package size: length × width × height ÷ a carrier’s divisor. Carriers bill the greater of this and actual weight.', example: 'A 12×10×8 in box ÷ 139 = 6.9 lb dim weight, even if it only weighs 3 lb.', related: ['billable-weight', 'parcel'], difficulty: 'intermediate' },
    { id: 'billable-weight', term: 'Billable weight', aliases: ['chargeable weight'], definition: 'The weight a carrier charges for: the greater of actual weight and dimensional weight, usually rounded up.', example: 'Actual 3 lb, dim 7 lb → billable weight 7 lb.', related: ['dimensional-weight'], difficulty: 'intermediate' },
    { id: 'shipping-zone', term: 'Shipping zone', definition: 'A carrier’s distance band between origin and destination. Higher zones usually cost more.', example: 'Shipping across the country might be zone 8; shipping across town might be zone 1 or 2.', related: ['carrier', 'service-level'] },
    { id: 'fulfillment', term: 'Fulfillment', definition: 'Everything that happens after an order is placed: receiving the order, picking, packing, labeling and shipping it.', example: 'A 3PL handles fulfillment so the founder can focus on marketing.', related: ['pick-and-pack', '3pl', 'handling-time'] },
    { id: 'pick-and-pack', term: 'Pick and pack', definition: 'Collecting ordered items from storage (pick) and packaging them for shipment (pack).', example: 'A 3PL may charge $3 per order for pick and pack plus $0.50 per extra item.', related: ['fulfillment', '3pl'] },
    { id: 'freight', term: 'Freight', definition: 'Shipments too large or heavy for parcel networks, usually moved on pallets or in containers.', example: 'Ten cartons of inventory on a pallet move as freight.', related: ['pallet', 'ltl', 'ftl'] },
    { id: 'pallet', term: 'Pallet', aliases: ['skid'], definition: 'A flat platform that lets a forklift move stacked cartons as one unit.', example: 'Warehouses often charge storage per pallet per month.', related: ['freight', 'ltl'] },
    { id: 'ltl', term: 'LTL (less-than-truckload)', aliases: ['LTL', 'less than truckload'], definition: 'A freight shipment that shares a truck with other shippers’ freight. You pay for your portion.', example: 'Three pallets to a warehouse usually ship LTL.', related: ['ftl', 'freight', 'pallet'], difficulty: 'intermediate' },
    { id: 'ftl', term: 'FTL (full truckload)', aliases: ['FTL', 'full truckload', 'TL'], definition: 'A freight shipment that books an entire truck, usually going directly from pickup to delivery.', example: 'Twenty-four pallets can fill a trailer and ship FTL.', related: ['ltl', 'freight'], difficulty: 'intermediate' },
    { id: 'fcl', term: 'FCL (full container load)', aliases: ['FCL', 'full container load'], definition: 'An ocean shipment where you rent an entire shipping container.', example: 'A brand ordering 8,000 units books a 40-foot container FCL.', related: ['lcl', 'freight-forwarder'], difficulty: 'intermediate' },
    { id: 'lcl', term: 'LCL (less than container load)', aliases: ['LCL', 'less than container load'], definition: 'An ocean shipment that shares a container with other shippers’ goods.', example: 'Four cubic meters of goods ship LCL.', related: ['fcl', 'freight-forwarder'], difficulty: 'intermediate' },
    { id: 'freight-forwarder', term: 'Freight forwarder', definition: 'A company that arranges shipments on your behalf — booking carriers, coordinating documents and often customs.', example: 'A forwarder books ocean space, arranges trucking and coordinates the customs broker.', related: ['fcl', 'lcl', 'customs-broker'], difficulty: 'intermediate' },
    { id: 'bill-of-lading', term: 'Bill of lading (BOL)', aliases: ['BOL', 'B/L'], definition: 'A shipping document issued by a carrier that acts as a receipt for goods and a contract of carriage.', example: 'The trucker signs the BOL at pickup to confirm the pallet count.', related: ['freight', 'commercial-invoice'], difficulty: 'intermediate' },
    { id: 'lead-time', term: 'Lead time', definition: 'The total time from placing a purchase order to having sellable stock: production, transit, customs and receiving.', example: '30 days production + 35 days shipping + 5 days receiving = 70-day lead time.', related: ['reorder-point', 'safety-stock'] },
    { id: 'customs', term: 'Customs', definition: 'The government process for inspecting, classifying and taxing goods that cross a border.', example: 'Imports wait at customs until the entry is filed and duties are paid.', related: ['duty', 'hs-code', 'customs-broker'] },
    { id: 'duty', term: 'Duty', aliases: ['tariff', 'import duty'], definition: 'A tax on imported goods, usually based on classification, value and country of origin.', example: 'A 12% duty on $8,000 of goods is $960.', related: ['customs', 'hs-code', 'landed-cost'] },
    { id: 'hs-code', term: 'HS code', aliases: ['harmonized system code', 'HTS code', 'tariff code'], definition: 'A standardized product classification number used by customs. The first 6 digits are international; countries add more.', example: 'Knitted cotton T-shirts fall under HS chapter 61.', related: ['customs', 'duty'], difficulty: 'intermediate' },
    { id: 'commercial-invoice', term: 'Commercial invoice', definition: 'The document declaring what is in an international shipment: description, value, origin and classification.', example: 'Customs uses the commercial invoice to calculate duty.', related: ['customs', 'hs-code'], difficulty: 'intermediate' },
    { id: 'customs-broker', term: 'Customs broker', definition: 'A licensed professional who files customs entries and helps importers comply with regulations.', example: 'A broker classifies your goods and pays duties on your behalf, then invoices you.', related: ['customs', 'freight-forwarder'], difficulty: 'intermediate' },
    { id: 'de-minimis', term: 'De minimis', definition: 'A value threshold below which some countries don’t collect duties or taxes on imports. Thresholds vary and have changed recently in several countries — always verify current rules.', example: 'A seller checks whether low-value parcels to a country still qualify before pricing shipping.', related: ['duty', 'customs'], difficulty: 'advanced' },
    { id: 'incoterms', term: 'Incoterms', definition: 'Standard trade terms from the International Chamber of Commerce that define who pays for each part of a shipment and when risk transfers.', example: '“FOB Shenzhen Incoterms 2020” tells you the seller’s job ends once goods are on board at Shenzhen.', related: ['exw', 'fob', 'cif', 'dap', 'ddp'], difficulty: 'intermediate' },
    { id: 'exw', term: 'EXW (Ex Works)', aliases: ['EXW', 'ex works'], definition: 'Incoterm where the buyer handles nearly everything from the seller’s premises onward.', example: 'Under EXW, you arrange pickup at the factory, export, freight and import.', related: ['incoterms', 'fob'], difficulty: 'intermediate' },
    { id: 'fob', term: 'FOB (Free On Board)', aliases: ['FOB', 'free on board'], definition: 'Incoterm (sea/inland waterway) where the seller loads goods on board the vessel at the origin port; risk then passes to the buyer.', example: '$4.00/unit FOB means you still pay ocean freight, insurance, duties and delivery.', related: ['incoterms', 'cif', 'landed-cost'], difficulty: 'intermediate' },
    { id: 'cif', term: 'CIF (Cost, Insurance and Freight)', aliases: ['CIF'], definition: 'Incoterm where the seller pays freight and minimum insurance to the destination port, but risk passes to the buyer once goods are loaded at origin.', example: 'Damage at sea under CIF is the buyer’s risk, though the seller bought the insurance.', related: ['incoterms', 'fob'], difficulty: 'advanced' },
    { id: 'dap', term: 'DAP (Delivered at Place)', aliases: ['DAP'], definition: 'Incoterm where the seller delivers to a named destination; the buyer handles import clearance and duties.', example: 'Goods arrive DAP at your warehouse and you pay the duties.', related: ['incoterms', 'ddp'], difficulty: 'advanced' },
    { id: 'ddp', term: 'DDP (Delivered Duty Paid)', aliases: ['DDP', 'delivered duty paid'], definition: 'Incoterm where the seller handles transport, import clearance and duties all the way to the buyer.', example: 'A $5.10/unit DDP quote can beat a $4.00 FOB quote once landed costs are compared.', related: ['incoterms', 'dap', 'landed-cost'], difficulty: 'intermediate' },
    { id: 'landed-cost', term: 'Landed cost', definition: 'The total cost of getting a product to your door: purchase price plus freight, insurance, duties and fees.', example: '$3,000 goods + $1,100 shipping and fees for 500 units = $8.20 landed cost per unit.', related: ['duty', 'cogs', 'fob'], difficulty: 'intermediate' },
    { id: '3pl', term: '3PL (third-party logistics)', aliases: ['3PL', 'third party logistics'], definition: 'An outside company that stores your inventory and fulfills orders for you.', example: 'A 3PL receives your pallets, stores them and ships each order.', related: ['fulfillment-center', 'pick-and-pack', 'asn'] },
    { id: 'fulfillment-center', term: 'Fulfillment center', definition: 'A warehouse designed to store goods and ship orders directly to customers.', example: 'Your 3PL operates two fulfillment centers to shorten delivery times.', related: ['3pl', 'fulfillment'] },
    { id: 'asn', term: 'ASN (advance shipping notice)', aliases: ['ASN', 'advance ship notice'], definition: 'A notice sent to a warehouse before an inbound shipment, listing what is arriving and when.', example: 'Submitting an ASN helps the 3PL receive your inventory faster.', related: ['receiving', '3pl'], difficulty: 'intermediate' },
    { id: 'receiving', term: 'Receiving', definition: 'The warehouse process of unloading, counting, inspecting and putting away inbound inventory.', example: 'Stock is not sellable until receiving is complete.', related: ['asn', '3pl'] },
    { id: 'cross-docking', term: 'Cross-docking', definition: 'Moving inbound goods directly to outbound shipments with little or no storage time.', example: 'A pallet arrives and its cartons leave on store-bound trucks the same day.', related: ['3pl', 'freight'], difficulty: 'advanced' },
    { id: 'sku', term: 'SKU (stock keeping unit)', aliases: ['SKU', 'stock keeping unit'], definition: 'Your internal code for each distinct sellable item — usually one per size/color variant.', example: 'HOOD-BLU-M and HOOD-BLU-L are separate SKUs.', related: ['inventory-turnover', 'reorder-point'] },
    { id: 'reorder-point', term: 'Reorder point', definition: 'The stock level at which you place your next purchase order: average daily sales × lead time + safety stock.', example: '20/day × 30 days + 150 = reorder at 750 units.', related: ['lead-time', 'safety-stock', 'stockout'], difficulty: 'intermediate' },
    { id: 'safety-stock', term: 'Safety stock', definition: 'Extra inventory kept as a buffer against demand spikes or late shipments.', example: 'An unreliable supplier means holding more safety stock.', related: ['reorder-point', 'stockout'], difficulty: 'intermediate' },
    { id: 'inventory-turnover', term: 'Inventory turnover', definition: 'How many times you sell through your average inventory in a period: COGS ÷ average inventory (at cost).', example: '$90,000 COGS ÷ $15,000 average inventory = 6 turns per year.', related: ['cogs', 'dead-stock'], difficulty: 'intermediate' },
    { id: 'stockout', term: 'Stockout', definition: 'Running out of an item customers still want to buy.', example: 'A bestseller stockout for 3 weeks costs sales and can hurt search rankings.', related: ['safety-stock', 'reorder-point'] },
    { id: 'overstock', term: 'Overstock', definition: 'Holding far more inventory than you are likely to sell soon.', example: 'Ordering a year of stock to get a discount can lead to overstock and storage fees.', related: ['dead-stock', 'inventory-turnover'] },
    { id: 'dead-stock', term: 'Dead stock', definition: 'Inventory that has stopped selling and is unlikely to sell at its current price.', example: '800 units of a discontinued color sitting for 6 months is dead stock.', related: ['overstock', 'inventory-turnover'] },
    { id: 'reverse-logistics', term: 'Reverse logistics', definition: 'Moving goods from customers back to the seller: returns, exchanges, repairs and recycling.', example: 'Inspecting returns and restocking resellable items is part of reverse logistics.', related: ['rma', 'restocking-fee'] },
    { id: 'rma', term: 'RMA (return merchandise authorization)', aliases: ['RMA', 'return authorization'], definition: 'An approval and reference number issued before a customer returns an item.', example: 'The RMA ties the returning box to its original order and reason.', related: ['reverse-logistics'] },
    { id: 'restocking-fee', term: 'Restocking fee', definition: 'A fee some sellers charge on returned items to cover handling. Rules vary by location — check consumer laws.', example: 'A 10% restocking fee on opened electronics.', related: ['reverse-logistics', 'rma'], difficulty: 'intermediate' },
  ]),
  // ───────────── E-commerce ─────────────
  ...group('ecommerce', [
    { id: 'ecommerce', term: 'E-commerce', definition: 'Buying and selling goods or services online.', example: 'A candle brand selling through its own website and a marketplace is an e-commerce business.', related: ['dtc', 'marketplace'] },
    { id: 'dtc', term: 'DTC (direct-to-consumer)', aliases: ['D2C', 'DTC', 'direct to consumer'], definition: 'Selling your own products directly to end customers, usually through your own website.', example: 'A sock brand selling on its own store instead of through retailers is DTC.', related: ['b2c', 'ecommerce'] },
    { id: 'b2c', term: 'B2C (business-to-consumer)', aliases: ['B2C'], definition: 'A business selling to individual consumers.', example: 'An online shoe store selling to shoppers is B2C.', related: ['b2b', 'dtc'] },
    { id: 'b2b', term: 'B2B (business-to-business)', aliases: ['B2B'], definition: 'A business selling to other businesses.', example: 'Selling packaging supplies to coffee shops is B2B.', related: ['b2c', 'wholesale'] },
    { id: 'marketplace', term: 'Marketplace', definition: 'A platform where many sellers list products to the platform’s shoppers, usually in exchange for fees.', example: 'Listing on a large marketplace gives access to its traffic, but you follow its rules and pay its fees.', related: ['dtc', 'transaction-fee'] },
    { id: 'business-model', term: 'Business model', definition: 'How a business creates value and makes money — who pays, for what and how often.', example: 'Dropshipping, print on demand and subscriptions are different e-commerce business models.', related: ['dropshipping', 'print-on-demand', 'subscription'] },
    { id: 'dropshipping', term: 'Dropshipping', definition: 'A model where the seller lists products and a supplier ships them directly to customers, so the seller holds no inventory.', example: 'A customer orders a lamp; the store forwards the order and the supplier ships it.', related: ['supplier', 'print-on-demand', 'business-model'] },
    { id: 'private-label', term: 'Private label', definition: 'Products made by a manufacturer but sold under your own brand.', example: 'A generic yoga mat produced with your logo and packaging is private label.', related: ['moq', 'supplier'] },
    { id: 'subscription', term: 'Subscription model', definition: 'Customers pay on a recurring schedule for ongoing products or access.', example: 'Monthly coffee deliveries are a subscription model.', related: ['ltv', 'retention'] },
    { id: 'supplier', term: 'Supplier', definition: 'A business that provides the products or materials you sell.', example: 'You compare three suppliers on price, quality, MOQ and lead time.', related: ['moq', 'lead-time', 'dropshipping'] },
    { id: 'moq', term: 'MOQ (minimum order quantity)', aliases: ['MOQ', 'minimum order quantity'], definition: 'The smallest number of units a supplier will produce or sell in one order.', example: 'A factory with a 500-unit MOQ won’t accept an order for 100.', related: ['supplier', 'private-label', 'cash-flow'] },
    { id: 'wholesale', term: 'Wholesale', definition: 'Selling products in bulk at a lower per-unit price, usually to retailers who resell them.', example: 'You sell mugs wholesale at $6 to shops that retail them at $15.', related: ['b2b', 'msrp'] },
    { id: 'msrp', term: 'MSRP', aliases: ['manufacturer suggested retail price', 'RRP'], definition: 'The manufacturer’s suggested retail price for a product.', example: 'A brand sets an MSRP of $40 so retailers price consistently.', related: ['wholesale', 'retail-price'] },
    { id: 'retail-price', term: 'Retail price', definition: 'The price a customer pays for a product.', example: 'A $28 retail price for a T-shirt that costs $12 to make.', related: ['markup', 'gross-margin'] },
    { id: 'product-research', term: 'Product research', definition: 'Investigating demand, competition, costs and customers before choosing a product to sell.', example: 'Checking reviews of competitor products reveals complaints you can solve.', related: ['niche', 'demand'] },
    { id: 'niche', term: 'Niche', definition: 'A specific, well-defined group of customers with shared needs or interests.', example: '“Gear for rock climbers with small hands” is a sharper niche than “sports gear.”', related: ['product-research', 'positioning'] },
    { id: 'demand', term: 'Demand', definition: 'How much customers want a product at a given price.', example: 'Search volume and competitor sales hint at demand.', related: ['product-research', 'price-elasticity'] },
    { id: 'price-elasticity', term: 'Price elasticity', definition: 'How strongly demand changes when price changes.', example: 'If a 10% price rise cuts sales by 30%, demand is very price-sensitive (elastic).', related: ['demand', 'retail-price'], difficulty: 'intermediate' },
    { id: 'value-proposition', term: 'Value proposition', definition: 'A clear statement of why a customer should buy from you instead of an alternative.', example: '“Leak-proof bottles with a lifetime warranty” is a value proposition.', related: ['positioning', 'niche'] },
    { id: 'session', term: 'Session', definition: 'One visit to your store by a shopper, including all pages they view.', example: '1,000 sessions and 20 orders gives a 2% conversion rate.', related: ['conversion-rate', 'traffic'] },
    { id: 'traffic', term: 'Traffic', definition: 'The visitors coming to your store or listing, from all sources.', example: 'Organic social, search and paid ads are traffic sources.', related: ['session', 'organic-traffic', 'paid-traffic'] },
    { id: 'organic-traffic', term: 'Organic traffic', definition: 'Visitors who arrive without you paying for that visit — from search results, social posts or word of mouth.', example: 'A viral video that sends 5,000 visitors is organic traffic.', related: ['paid-traffic', 'traffic'] },
    { id: 'paid-traffic', term: 'Paid traffic', definition: 'Visitors who arrive from ads you pay for.', example: 'Clicks from a social ad campaign are paid traffic.', related: ['organic-traffic', 'cpc', 'roas'] },
    { id: 'conversion-rate', term: 'Conversion rate', aliases: ['CVR'], definition: 'The percentage of visitors (or sessions) that complete a goal, usually a purchase: orders ÷ sessions × 100.', example: '30 orders from 1,500 sessions = 2% conversion rate.', related: ['session', 'aov', 'cart-abandonment'] },
    { id: 'aov', term: 'AOV (average order value)', aliases: ['AOV', 'average order value'], definition: 'Average revenue per order: total revenue ÷ number of orders.', example: '$6,000 revenue from 150 orders = $40 AOV.', related: ['upsell', 'bundle', 'conversion-rate'] },
    { id: 'cart-abandonment', term: 'Cart abandonment', definition: 'When shoppers add items to their cart but leave without buying.', example: 'Surprise shipping costs at checkout are a common cause of cart abandonment.', related: ['conversion-rate', 'checkout'] },
    { id: 'checkout', term: 'Checkout', definition: 'The final steps where a shopper enters shipping and payment details to place an order.', example: 'Removing unnecessary checkout fields can lift conversion.', related: ['cart-abandonment', 'payment-processor'] },
    { id: 'upsell', term: 'Upsell', definition: 'Encouraging a customer to buy a higher-value version or add more of the same item.', example: '“Upgrade to the 3-pack and save 15%.”', related: ['cross-sell', 'aov'] },
    { id: 'cross-sell', term: 'Cross-sell', definition: 'Suggesting a related, complementary product.', example: 'Offering a phone case when someone buys a screen protector.', related: ['upsell', 'bundle'] },
    { id: 'bundle', term: 'Bundle', definition: 'Several products sold together, often at a combined discount.', example: 'Shampoo + conditioner bundle for $30 instead of $34 separately.', related: ['aov', 'cross-sell'] },
    { id: 'customer-acquisition', term: 'Customer acquisition', definition: 'The process and channels used to win new customers.', example: 'Creator partnerships and search ads are customer acquisition channels.', related: ['cac', 'paid-traffic'] },
    { id: 'social-proof', term: 'Social proof', definition: 'Evidence that other people buy and like a product — reviews, ratings, photos, testimonials.', example: '“4.8 stars from 2,300 reviews” is social proof.', related: ['conversion-rate', 'ugc'] },
    { id: 'payment-processor', term: 'Payment processor', definition: 'A service that handles card and wallet payments between the customer, banks and your store, for a fee.', example: 'Your processor charges a percentage plus a fixed fee per transaction.', related: ['transaction-fee', 'chargeback'] },
    { id: 'chargeback', term: 'Chargeback', definition: 'A payment reversal initiated through the customer’s bank or card issuer after a dispute.', example: 'A customer says an order never arrived and files a chargeback; you submit tracking as evidence.', related: ['payment-processor', 'tracking-number'], difficulty: 'intermediate' },
  ]),
  // ───────────── Business Finance ─────────────
  ...group('finance', [
    { id: 'revenue', term: 'Revenue', aliases: ['sales', 'top line'], definition: 'Money brought in from sales before any costs are subtracted.', example: '200 orders × $30 = $6,000 revenue.', related: ['gross-profit', 'net-profit'] },
    { id: 'cogs', term: 'COGS (cost of goods sold)', aliases: ['COGS', 'cost of goods sold'], definition: 'The direct cost of the products you sold — product cost and often inbound shipping and packaging.', example: 'If each mug costs $5 landed and you sold 300, COGS is $1,500.', related: ['gross-profit', 'landed-cost', 'gross-margin'] },
    { id: 'gross-profit', term: 'Gross profit', definition: 'Revenue minus COGS.', example: '$6,000 revenue − $2,400 COGS = $3,600 gross profit.', related: ['revenue', 'cogs', 'gross-margin'] },
    { id: 'gross-margin', term: 'Gross margin', definition: 'Gross profit as a percentage of revenue: (revenue − COGS) ÷ revenue × 100.', example: '$3,600 ÷ $6,000 = 60% gross margin.', related: ['gross-profit', 'markup', 'net-margin'] },
    { id: 'net-profit', term: 'Net profit', aliases: ['net income', 'bottom line'], definition: 'What is left after subtracting all costs — COGS, operating expenses, fees and taxes — from revenue.', example: '$3,600 gross profit − $2,800 expenses = $800 net profit (before tax).', related: ['gross-profit', 'net-margin', 'operating-expenses'] },
    { id: 'net-margin', term: 'Net margin', definition: 'Net profit as a percentage of revenue.', example: '$800 net profit ÷ $6,000 revenue = 13.3% net margin.', related: ['net-profit', 'gross-margin'] },
    { id: 'markup', term: 'Markup', definition: 'How much you add on top of cost, as a percentage of cost: (price − cost) ÷ cost × 100.', example: 'Cost $10, price $25 → markup 150% (but gross margin is 60%).', related: ['gross-margin', 'retail-price'] },
    { id: 'operating-expenses', term: 'Operating expenses', aliases: ['OPEX', 'overhead'], definition: 'Costs of running the business that aren’t COGS: software, ads, salaries, rent and so on.', example: 'Store subscription, email tool and ad spend are operating expenses.', related: ['fixed-costs', 'net-profit'] },
    { id: 'fixed-costs', term: 'Fixed costs', definition: 'Costs that stay the same regardless of how much you sell, within a range.', example: 'A $39 monthly store plan is a fixed cost.', related: ['variable-costs', 'breakeven'] },
    { id: 'variable-costs', term: 'Variable costs', definition: 'Costs that rise with each unit or order sold.', example: 'Product cost, packaging and payment fees are variable costs.', related: ['fixed-costs', 'contribution-margin'] },
    { id: 'contribution-margin', term: 'Contribution margin', definition: 'Price minus all variable costs per unit — what each sale contributes toward fixed costs and profit.', example: '$30 price − $18 variable costs = $12 contribution margin per unit.', related: ['breakeven', 'variable-costs', 'unit-economics'], difficulty: 'intermediate' },
    { id: 'breakeven', term: 'Breakeven point', aliases: ['breakeven', 'break-even'], definition: 'The sales level where total revenue equals total costs: fixed costs ÷ contribution margin per unit.', example: '$1,200 fixed costs ÷ $12 per unit = 100 units to break even.', related: ['contribution-margin', 'fixed-costs'], difficulty: 'intermediate' },
    { id: 'cash-flow', term: 'Cash flow', definition: 'The movement of cash in and out of a business over a period. Profitable businesses can still run out of cash.', example: 'Paying $8,000 for inventory in March that sells through June creates negative cash flow in March.', related: ['working-capital', 'net-profit'] },
    { id: 'working-capital', term: 'Working capital', definition: 'Short-term assets (cash, inventory, receivables) minus short-term liabilities — the cushion for day-to-day operations.', example: 'Inventory purchases tie up working capital until the stock sells.', related: ['cash-flow', 'inventory-turnover'], difficulty: 'advanced' },
    { id: 'roi', term: 'ROI (return on investment)', aliases: ['ROI', 'return on investment'], definition: 'Profit from an investment relative to its cost: (gain − cost) ÷ cost × 100.', example: 'Spend $500 on a photo shoot that adds $1,500 profit → ROI = 200%.', related: ['roas', 'payback-period'] },
    { id: 'cac', term: 'CAC (customer acquisition cost)', aliases: ['CAC', 'customer acquisition cost'], definition: 'Average cost to acquire one new customer: marketing and sales spend ÷ new customers.', example: '$2,000 in ads and creator fees for 80 new customers = $25 CAC.', related: ['ltv', 'ltv-cac-ratio', 'customer-acquisition'], difficulty: 'intermediate' },
    { id: 'ltv', term: 'LTV (customer lifetime value)', aliases: ['LTV', 'CLV', 'CLTV', 'lifetime value'], definition: 'The total gross profit (or revenue) a customer brings over their relationship with you.', example: 'AOV $40 × 3 orders × 60% margin = $72 gross-profit LTV.', related: ['cac', 'ltv-cac-ratio', 'retention'], difficulty: 'intermediate' },
    { id: 'ltv-cac-ratio', term: 'LTV:CAC ratio', definition: 'Lifetime value divided by acquisition cost — whether customers are worth what you pay to get them.', example: '$72 LTV ÷ $24 CAC = 3:1, often cited as a healthy benchmark.', related: ['ltv', 'cac'], difficulty: 'advanced' },
    { id: 'payback-period', term: 'Payback period', definition: 'How long it takes for profit from an investment (or a customer) to repay its cost.', example: 'CAC $30 and $10 gross profit per month → 3-month payback.', related: ['cac', 'roi'], difficulty: 'advanced' },
    { id: 'unit-economics', term: 'Unit economics', definition: 'The revenue and costs associated with a single unit — one product, order or customer.', example: 'Per order: $40 revenue − $16 COGS − $6 shipping − $2 fees − $10 ads = $6 profit.', related: ['contribution-margin', 'cac'], difficulty: 'intermediate' },
    { id: 'budget', term: 'Budget', definition: 'A plan for expected income and spending over a period.', example: 'A monthly budget caps ad spend at $1,000 until ROAS is proven.', related: ['forecast', 'cash-flow'] },
    { id: 'forecast', term: 'Forecast', definition: 'An estimate of future sales, costs or cash based on assumptions.', example: 'Forecasting 20% higher sales in December to plan inventory.', related: ['budget', 'reorder-point'], difficulty: 'intermediate' },
    { id: 'transaction-fee', term: 'Transaction fee', aliases: ['processing fee'], definition: 'A fee charged per sale by a payment processor or platform, often a percentage plus a fixed amount.', example: '2.9% + $0.30 on a $40 order = $1.46.', related: ['payment-processor', 'variable-costs'] },
    { id: 'sales-tax', term: 'Sales tax / VAT', aliases: ['VAT', 'GST', 'sales tax'], definition: 'A consumption tax collected from the buyer at sale and paid to the government. Rules depend on location — consult official guidance or an accountant.', example: 'The checkout adds sales tax based on the customer’s address where required.', related: ['net-profit'], difficulty: 'intermediate' },
  ]),
  // ───────────── Marketing ─────────────
  ...group('marketing', [
    { id: 'impressions', term: 'Impressions', definition: 'The number of times content or an ad was displayed.', example: 'An ad shown 50,000 times has 50,000 impressions.', related: ['reach', 'cpm', 'ctr'] },
    { id: 'reach', term: 'Reach', definition: 'The number of unique people who saw your content or ad.', example: '50,000 impressions with a reach of 20,000 means people saw it 2.5 times on average.', related: ['impressions', 'frequency'] },
    { id: 'frequency', term: 'Frequency', definition: 'Average number of times each person saw an ad: impressions ÷ reach.', example: '30,000 impressions ÷ 10,000 reach = frequency of 3.', related: ['reach', 'impressions'], difficulty: 'intermediate' },
    { id: 'ctr', term: 'CTR (click-through rate)', aliases: ['CTR', 'click through rate'], definition: 'Clicks ÷ impressions × 100.', example: '400 clicks from 20,000 impressions = 2% CTR.', related: ['impressions', 'cpc', 'hook'] },
    { id: 'cpm', term: 'CPM (cost per mille)', aliases: ['CPM', 'cost per thousand'], definition: 'Cost per 1,000 impressions: ad spend ÷ impressions × 1,000.', example: '$150 for 30,000 impressions = $5 CPM.', related: ['impressions', 'cpc'] },
    { id: 'cpc', term: 'CPC (cost per click)', aliases: ['CPC', 'cost per click'], definition: 'Ad spend ÷ clicks.', example: '$200 spend for 400 clicks = $0.50 CPC.', related: ['ctr', 'cpm', 'cpa'] },
    { id: 'cpa', term: 'CPA (cost per acquisition)', aliases: ['CPA', 'cost per purchase'], definition: 'Ad spend ÷ conversions (often purchases).', example: '$500 ad spend that drives 20 purchases = $25 CPA.', related: ['cac', 'roas'], difficulty: 'intermediate' },
    { id: 'roas', term: 'ROAS (return on ad spend)', aliases: ['ROAS', 'return on ad spend'], definition: 'Revenue from ads ÷ ad spend. It measures revenue, not profit.', example: '$2,000 revenue from $500 ad spend = 4.0 ROAS (4×).', related: ['breakeven-roas', 'cpa', 'roi'], difficulty: 'intermediate' },
    { id: 'breakeven-roas', term: 'Breakeven ROAS', definition: 'The ROAS at which ad-driven sales cover their own costs: 1 ÷ contribution margin %.', example: 'With a 40% contribution margin, breakeven ROAS = 1 ÷ 0.40 = 2.5.', related: ['roas', 'contribution-margin'], difficulty: 'advanced' },
    { id: 'engagement-rate', term: 'Engagement rate', definition: 'Interactions (likes, comments, shares, saves) relative to views or followers.', example: '1,200 interactions on 20,000 views = 6% engagement rate.', related: ['impressions', 'creator'] },
    { id: 'funnel', term: 'Marketing funnel', aliases: ['funnel', 'sales funnel'], definition: 'The stages a customer moves through — awareness, consideration, conversion, loyalty — with fewer people at each stage.', example: '10,000 viewers → 500 store visitors → 15 buyers.', related: ['conversion-rate', 'retargeting'] },
    { id: 'retargeting', term: 'Retargeting', aliases: ['remarketing'], definition: 'Showing ads to people who already interacted with your brand, like site visitors or cart abandoners.', example: 'Shoppers who viewed a product see an ad reminding them of it.', related: ['funnel', 'cart-abandonment'], difficulty: 'intermediate' },
    { id: 'hook', term: 'Hook', definition: 'The first moment of content (often 1–3 seconds) designed to stop the scroll and earn attention.', example: '“I tested 5 cheap phone tripods so you don’t have to” is a hook.', related: ['ugc', 'ctr'] },
    { id: 'call-to-action', term: 'Call to action (CTA)', aliases: ['CTA'], definition: 'A clear instruction telling the audience what to do next.', example: '“Tap the product link to grab yours before the restock sells out.”', related: ['hook', 'conversion-rate'] },
    { id: 'positioning', term: 'Positioning', definition: 'The place you want your brand to occupy in customers’ minds compared with alternatives.', example: '“The most durable budget backpack for students.”', related: ['value-proposition', 'branding'] },
    { id: 'branding', term: 'Branding', definition: 'The name, look, voice and promises that make a business recognizable and trusted.', example: 'Consistent colors, tone and packaging build branding over time.', related: ['positioning'] },
    { id: 'retention', term: 'Customer retention', aliases: ['retention', 'repeat purchase'], definition: 'Keeping customers coming back to buy again.', example: 'Post-purchase emails and loyalty perks improve retention.', related: ['ltv', 'email-marketing'] },
    { id: 'email-marketing', term: 'Email marketing', definition: 'Sending emails to subscribers who agreed to hear from you — welcome series, launches, abandoned-cart reminders.', example: 'An abandoned-cart email recovers a share of lost orders.', related: ['retention', 'cart-abandonment'] },
    { id: 'ab-test', term: 'A/B test', aliases: ['split test', 'AB test'], definition: 'Comparing two versions of something by showing each to a similar audience and measuring which performs better.', example: 'Testing two thumbnails to see which gets a higher CTR.', related: ['ctr', 'conversion-rate'], difficulty: 'intermediate' },
  ]),
  // ───────────── Creator Marketing ─────────────
  ...group('creator', [
    { id: 'creator', term: 'Creator', aliases: ['influencer', 'content creator'], definition: 'A person who makes content for an audience and may promote products to that audience.', example: 'A home-cooking creator with 40,000 engaged followers reviews your spice kit.', related: ['ugc', 'gifting', 'affiliate-link'] },
    { id: 'micro-creator', term: 'Micro-creator', aliases: ['micro-influencer', 'nano creator'], definition: 'A creator with a smaller but often highly engaged audience (commonly cited as roughly 10k–100k followers; definitions vary).', example: 'Ten micro-creators can outperform one celebrity for a niche product.', related: ['creator', 'engagement-rate'] },
    { id: 'ugc', term: 'UGC (user-generated content)', aliases: ['UGC', 'user generated content'], definition: 'Authentic-looking content made by customers or creators rather than the brand. Brands often pay creators to make UGC for ads.', example: 'A creator films an unboxing that the brand uses in its ads.', related: ['creator', 'usage-rights', 'social-proof'] },
    { id: 'gifting', term: 'Gifting', aliases: ['product seeding', 'seeding'], definition: 'Sending free products to creators with no guaranteed obligation to post.', example: 'You gift 30 creators; 8 post organically.', related: ['creator', 'affiliate-link'] },
    { id: 'affiliate-link', term: 'Affiliate link', definition: 'A trackable link or code that attributes sales to a specific creator so they can earn commission.', example: 'A creator’s unique link earns them 15% of each sale.', related: ['affiliate-commission', 'discount-code'] },
    { id: 'affiliate-commission', term: 'Affiliate commission', aliases: ['commission'], definition: 'A percentage or fixed amount of each attributed sale paid to the promoter.', example: '15% commission on a $40 order = $6.', related: ['affiliate-link', 'flat-fee'] },
    { id: 'flat-fee', term: 'Flat fee', definition: 'A fixed payment for content or a post, regardless of sales results.', example: '$300 for one video with two rounds of revisions.', related: ['affiliate-commission', 'hybrid-deal'] },
    { id: 'hybrid-deal', term: 'Hybrid deal', definition: 'A creator deal that combines a smaller flat fee with commission on sales.', example: '$150 flat + 10% commission shares risk between brand and creator.', related: ['flat-fee', 'affiliate-commission'], difficulty: 'intermediate' },
    { id: 'discount-code', term: 'Discount code', aliases: ['promo code', 'coupon code'], definition: 'A code that gives the buyer a discount and can attribute the sale to a creator.', example: 'MAYA10 gives 10% off and tracks Maya’s sales.', related: ['affiliate-link'] },
    { id: 'usage-rights', term: 'Usage rights', definition: 'Permission for the brand to reuse a creator’s content, defined by channel, duration and format.', example: 'Paid usage for 90 days on social ads.', related: ['ugc', 'whitelisting', 'exclusivity'], difficulty: 'intermediate' },
    { id: 'whitelisting', term: 'Whitelisting', aliases: ['spark ads', 'partnership ads', 'creator licensing'], definition: 'Running paid ads through or from a creator’s account or identity, with their permission.', example: 'A brand boosts a creator’s best-performing post as an ad from the creator’s handle.', related: ['usage-rights', 'ugc'], difficulty: 'advanced' },
    { id: 'exclusivity', term: 'Exclusivity', definition: 'A contract term preventing a creator from promoting competing brands for a set time.', example: '30 days of category exclusivity after posting.', related: ['usage-rights', 'creator-brief'], difficulty: 'intermediate' },
    { id: 'creator-brief', term: 'Creator brief', definition: 'A short document explaining the product, key messages, must-dos, don’ts and deadlines for creator content.', example: 'A one-page brief with 3 talking points, required disclosure and posting window.', related: ['creator', 'exclusivity'] },
    { id: 'disclosure', term: 'Sponsorship disclosure', aliases: ['#ad', 'paid partnership'], definition: 'Clearly telling the audience that content is paid, gifted or affiliated. Required by advertising rules in many countries.', example: 'Using the platform’s paid-partnership label and saying “gifted by…” in the video.', related: ['creator', 'gifting'] },
  ]),
  // ───────────── Print on Demand ─────────────
  ...group('pod', [
    { id: 'print-on-demand', term: 'Print on demand (POD)', aliases: ['POD'], definition: 'A model where each product is printed only after it is ordered, usually by a partner that also ships it.', example: 'A customer orders a hoodie; the POD partner prints and ships it in a few days.', related: ['pod-supplier', 'blank', 'dropshipping'] },
    { id: 'pod-supplier', term: 'POD supplier', aliases: ['print provider'], definition: 'A company that prints and fulfills POD orders on your behalf.', example: 'You compare POD suppliers on base cost, print quality and production time.', related: ['print-on-demand', 'base-cost'] },
    { id: 'blank', term: 'Blank', aliases: ['blanks', 'apparel blank'], definition: 'An unprinted product (T-shirt, hoodie, tote, mug) that gets decorated with your design.', example: 'A heavyweight cotton tee blank feels more premium than a thin one.', related: ['print-on-demand', 'base-cost'] },
    { id: 'base-cost', term: 'Base cost', definition: 'What a POD supplier charges you per item (blank + printing), before shipping.', example: 'A $12.50 base cost tee sold at $28 leaves $15.50 before shipping and fees.', related: ['cogs', 'pod-supplier'] },
    { id: 'dtg', term: 'DTG (direct-to-garment)', aliases: ['DTG', 'direct to garment'], definition: 'Printing with inkjet-style printers directly onto fabric. Great for detailed, multicolor designs in small quantities.', example: 'A full-color illustration on a single cotton tee is printed DTG.', related: ['screen-printing', 'dtf'], difficulty: 'intermediate' },
    { id: 'screen-printing', term: 'Screen printing', definition: 'Pushing ink through a mesh screen, one screen per color. Cheap per unit at volume, but setup makes it costly for small runs.', example: 'A 2-color logo on 300 shirts is ideal for screen printing.', related: ['dtg', 'moq'], difficulty: 'intermediate' },
    { id: 'dtf', term: 'DTF (direct-to-film)', aliases: ['DTF', 'direct to film'], definition: 'Printing a design onto film, then heat-transferring it to the product. Works on many fabrics and colors.', example: 'DTF is used for vivid prints on polyester blends.', related: ['dtg'], difficulty: 'intermediate' },
    { id: 'sublimation', term: 'Sublimation', definition: 'Using heat to turn special ink into gas that bonds with polyester or coated surfaces. Produces all-over prints that don’t crack, but needs light-colored polyester or coated items.', example: 'All-over-print polyester shirts and coated mugs use sublimation.', related: ['dtg', 'blank'], difficulty: 'intermediate' },
    { id: 'embroidery', term: 'Embroidery', definition: 'Stitching a design into fabric with thread. Premium feel; best for simple designs with few colors.', example: 'A small embroidered logo on a cap.', related: ['dtg'] },
    { id: 'mockup', term: 'Mockup', definition: 'A realistic image of your design on the product, used for listings before anything is produced.', example: 'Lifestyle mockups show the hoodie on a model in a café.', related: ['print-file', 'sample'] },
    { id: 'print-file', term: 'Print file', definition: 'The final artwork file the printer uses, sized to the print area at the required resolution.', example: 'A 4500 × 5400 px PNG with a transparent background at 300 DPI.', related: ['dpi', 'print-area', 'vector'] },
    { id: 'print-area', term: 'Print area', definition: 'The maximum region of a product that can be printed.', example: 'A tee’s front print area might be about 12 × 16 inches.', related: ['print-file'] },
    { id: 'dpi', term: 'DPI (dots per inch)', aliases: ['DPI', 'PPI', 'resolution'], definition: 'Print resolution. Apparel printers commonly ask for 300 DPI at final print size.', example: 'A 12-inch-wide print at 300 DPI needs 3,600 pixels across.', related: ['print-file', 'vector'], difficulty: 'intermediate' },
    { id: 'vector', term: 'Vector artwork', aliases: ['vector', 'SVG'], definition: 'Artwork made of mathematical shapes that scales to any size without blurring.', example: 'A logo saved as a vector file prints sharp on a sticker or a billboard.', related: ['dpi', 'print-file'], difficulty: 'intermediate' },
    { id: 'sample', term: 'Sample', aliases: ['test order'], definition: 'A unit you order for yourself to check quality, fit and print before selling.', example: 'Ordering a sample reveals the ink looks darker than on screen.', related: ['mockup', 'pod-supplier'] },
    { id: 'production-time', term: 'Production time', definition: 'Time a supplier needs to make an item after the order arrives, before it ships.', example: 'POD production of 2–5 business days plus transit.', related: ['handling-time', 'lead-time'] },
  ]),
  // ───────────── TikTok Shop / Social commerce ─────────────
  ...group('tiktok', [
    { id: 'social-commerce', term: 'Social commerce', definition: 'Buying products directly inside social platforms, often from videos, live streams or creator posts.', example: 'A viewer taps a product link in a video and checks out without leaving the app.', related: ['shoppable-video', 'live-shopping'] },
    { id: 'shoppable-video', term: 'Shoppable video', definition: 'A video with a linked product the viewer can tap to view and buy.', example: 'A creator’s demo video with a product link attached.', related: ['social-commerce', 'affiliate-creator'] },
    { id: 'live-shopping', term: 'Live shopping', aliases: ['LIVE selling', 'livestream shopping'], definition: 'Selling products during a live stream where viewers can ask questions and buy in real time.', example: 'A 60-minute LIVE demonstrating skincare with limited-time bundles.', related: ['social-commerce'] },
    { id: 'affiliate-creator', term: 'Affiliate creator', definition: 'A creator who promotes a seller’s products through a platform’s affiliate program and earns commission on attributed sales.', example: 'An affiliate creator adds your product to their showcase and posts a review.', related: ['affiliate-commission', 'target-collaboration'] },
    { id: 'open-collaboration', term: 'Open collaboration', aliases: ['open plan'], definition: 'An affiliate offer that any eligible creator can join at a set commission rate (naming varies by platform).', example: 'You set 12% commission open to all creators to get broad exposure.', related: ['target-collaboration', 'affiliate-creator'], difficulty: 'intermediate' },
    { id: 'target-collaboration', term: 'Targeted collaboration', aliases: ['target plan'], definition: 'An affiliate offer sent to specific creators, often with a custom commission rate (naming varies by platform).', example: 'You invite 15 well-matched creators at 20% commission.', related: ['open-collaboration', 'affiliate-creator'], difficulty: 'intermediate' },
    { id: 'free-sample', term: 'Free sample request', definition: 'When a creator asks for a free product to make content, and the seller approves or declines based on fit.', example: 'You approve samples for creators whose audience matches your niche.', related: ['gifting', 'affiliate-creator'] },
    { id: 'gmv', term: 'GMV (gross merchandise value)', aliases: ['GMV', 'gross merchandise volume'], definition: 'Total value of goods sold through a channel before fees, refunds and costs.', example: '$10,000 GMV is not the same as $10,000 profit.', related: ['revenue', 'net-profit'], difficulty: 'intermediate' },
    { id: 'product-listing', term: 'Product listing', definition: 'The product page on a marketplace or shop: title, images, video, description, price and variants.', example: 'A clear listing with real photos reduces returns.', related: ['sku', 'conversion-rate'] },
    { id: 'seller-center', term: 'Seller center', aliases: ['seller dashboard'], definition: 'The platform dashboard where sellers manage listings, orders, promotions and analytics.', example: 'You track late shipments in your seller center.', related: ['product-listing'] },
    { id: 'policy-violation', term: 'Policy violation', definition: 'Breaking a platform’s rules (prohibited products, misleading claims, late shipping) — can lead to penalties or account restrictions.', example: 'Claiming a cream “cures acne” may violate health-claim policies.', related: ['seller-center'] },
    { id: 'shop-performance', term: 'Shop performance score', aliases: ['seller rating', 'account health'], definition: 'A platform’s rating of seller reliability based on factors like shipping speed, cancellations and reviews. Exact formulas vary and change.', example: 'Late shipments lower your score and can limit visibility.', related: ['policy-violation', 'handling-time'], difficulty: 'intermediate' },
  ]),
]);

export const glossaryById = new Map(glossary.map((t) => [t.id, t]));
export const GLOSSARY_CATEGORY_LABEL: Record<string, string> = {
  shipping: 'Shipping & Logistics',
  ecommerce: 'E-commerce',
  finance: 'Finance',
  marketing: 'Marketing',
  creator: 'Creator Marketing',
  pod: 'Print on Demand',
  tiktok: 'Social Commerce',
};
